create table "dev_control"."dev_work_runs" (
  "id"          bigint                   generated by default as identity not null,
  "request_id"  bigint                   not null,
  "run_status"  text                     not null default 'queued'::text,
  "started_at"  timestamp with time zone,
  "finished_at" timestamp with time zone,
  "result"      jsonb,
  "created_at"  timestamp with time zone not null default now(),
  constraint "dev_work_runs_pkey" primary key (id),
  constraint "dev_work_runs_request_id_fkey" foreign key (request_id) references dev_control.dev_work_requests(id) on delete cascade
);

grant delete, insert, maintain, references, select, trigger, truncate, update on table "dev_control"."dev_work_runs" to "postgres";
